import{_ as i,c as n,o as a,ag as r}from"./chunks/framework.DfL_BkQ-.js";const o=JSON.parse('{"title":"Leitfaden zur Berechtigung für Bildschirmaufnahme (macOS)","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/screen-recording.md","filePath":"de/guide/screen-recording.md","lastUpdated":1794112334000}'),t={name:"de/guide/screen-recording.md"};function s(h,e,l,u,c,d){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="leitfaden-zur-berechtigung-fur-bildschirmaufnahme-macos" tabindex="-1">Leitfaden zur Berechtigung für Bildschirmaufnahme (macOS) <a class="header-anchor" href="#leitfaden-zur-berechtigung-fur-bildschirmaufnahme-macos" aria-label="Permalink to &quot;Leitfaden zur Berechtigung für Bildschirmaufnahme (macOS)&quot;">​</a></h1><h2 id="warum-benotigt-nicasa-die-berechtigung-zur-bildschirmaufnahme" tabindex="-1">Warum benötigt Nicasa die Berechtigung zur Bildschirmaufnahme? <a class="header-anchor" href="#warum-benotigt-nicasa-die-berechtigung-zur-bildschirmaufnahme" aria-label="Permalink to &quot;Warum benötigt Nicasa die Berechtigung zur Bildschirmaufnahme?&quot;">​</a></h2><p>Unter macOS müssen Screenshot- und Bildschirmaufnahme-Apps die Berechtigung zur Bildschirmaufnahme erhalten, um Pixel vom Display lesen zu dürfen.</p><p>Seit macOS 10.15 Catalina hat Apple strengere Datenschutzvorkehrungen eingeführt. Jede App, die Bildschirminhalte erfasst – einschließlich Screenshots – muss vom Nutzer ausdrücklich genehmigt werden.</p><p>Das gilt für alle Apps, auch für solche aus dem Mac App Store.</p><p><strong>Ohne diese Berechtigung kann Nicasa keine Screenshots erstellen und keine Bildschirminhalte aufnehmen.</strong></p><h2 id="so-aktivierst-du-die-berechtigung-zur-bildschirmaufnahme" tabindex="-1">So aktivierst du die Berechtigung zur Bildschirmaufnahme <a class="header-anchor" href="#so-aktivierst-du-die-berechtigung-zur-bildschirmaufnahme" aria-label="Permalink to &quot;So aktivierst du die Berechtigung zur Bildschirmaufnahme&quot;">​</a></h2><p>Folge diesen Schritten:</p><ol><li>Öffne die <strong>Systemeinstellungen</strong></li><li>Gehe zu <strong>Datenschutz &amp; Sicherheit</strong></li><li>Wähle <strong>Bildschirmaufnahme</strong></li><li>Suche <strong>Nicasa</strong> in der Liste und setze ein Häkchen</li></ol><p>Wenn die App bereits lief, starte Nicasa nach dem Erteilen der Berechtigung neu.</p><h2 id="wenn-der-berechtigungsdialog-nicht-erschienen-ist" tabindex="-1">Wenn der Berechtigungsdialog nicht erschienen ist <a class="header-anchor" href="#wenn-der-berechtigungsdialog-nicht-erschienen-ist" aria-label="Permalink to &quot;Wenn der Berechtigungsdialog nicht erschienen ist&quot;">​</a></h2><p>Der Dialog erscheint normalerweise, wenn die App zum ersten Mal versucht, den Bildschirm zu erfassen.</p><p>Wenn du den Dialog nicht gesehen hast, kann das daran liegen, dass:</p><ul><li>die Berechtigungsanfrage zuvor abgelehnt wurde</li><li>macOS den Berechtigungsstatus zwischengespeichert hat</li><li>die App die Erfassung versucht hat, bevor der Dialog erscheinen konnte</li></ul><p>In diesem Fall musst du die Berechtigung möglicherweise zurücksetzen.</p><h2 id="berechtigung-zur-bildschirmaufnahme-zurucksetzen" tabindex="-1">Berechtigung zur Bildschirmaufnahme zurücksetzen <a class="header-anchor" href="#berechtigung-zur-bildschirmaufnahme-zurucksetzen" aria-label="Permalink to &quot;Berechtigung zur Bildschirmaufnahme zurücksetzen&quot;">​</a></h2><p>Du kannst die Berechtigung mit folgendem Befehl im Terminal zurücksetzen:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ScreenCapture</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.nicasa.nue</span></span></code></pre></div><p>Nach dem Ausführen des Befehls:</p><ol><li>Starte Nicasa neu</li><li>Löse die Screenshot-Funktion erneut aus</li><li>macOS sollte den Berechtigungsdialog erneut anzeigen</li></ol><h2 id="wenn-das-zurucksetzen-nicht-hilft" tabindex="-1">Wenn das Zurücksetzen nicht hilft <a class="header-anchor" href="#wenn-das-zurucksetzen-nicht-hilft" aria-label="Permalink to &quot;Wenn das Zurücksetzen nicht hilft&quot;">​</a></h2><p>In seltenen Fällen behält macOS einen ungültigen Berechtigungsstatus bei.</p><p>Wenn das Zurücksetzen der Berechtigung das Problem nicht löst, versuche folgende Schritte:</p><ol><li>Beende Nicasa</li><li>Lösche Nicasa aus deinem Programme-Ordner</li><li>Installiere die neueste Version aus dem Mac App Store neu</li><li>Starte die App erneut</li><li>Wähle <strong>Erlauben</strong>, wenn macOS nach der Berechtigung zur Bildschirmaufnahme fragt</li></ol><p>Eine Neuinstallation kann macOS dazu bringen, den Berechtigungseintrag neu anzulegen.</p><h2 id="alternative-manuelle-losung" tabindex="-1">Alternative manuelle Lösung <a class="header-anchor" href="#alternative-manuelle-losung" aria-label="Permalink to &quot;Alternative manuelle Lösung&quot;">​</a></h2><p>Du kannst die Berechtigung auch manuell umschalten:</p><ol><li>Öffne die <strong>Systemeinstellungen</strong></li><li>Gehe zu <strong>Datenschutz &amp; Sicherheit</strong></li><li>Öffne <strong>Bildschirmaufnahme</strong></li><li>Entferne das Häkchen bei Nicasa und setze es erneut</li><li>Starte Nicasa neu</li></ol><h2 id="sicherheitshinweis" tabindex="-1">Sicherheitshinweis <a class="header-anchor" href="#sicherheitshinweis" aria-label="Permalink to &quot;Sicherheitshinweis&quot;">​</a></h2><p>Die Berechtigung zur Bildschirmaufnahme erlaubt Nicasa nicht, dein System zu steuern.</p><p>Sie erlaubt der App lediglich, Bildschirmpixel für die Screenshot- und Aufnahmefunktionen zu lesen.</p><p>Du kannst diese Berechtigung jederzeit widerrufen unter: <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit → Bildschirmaufnahme</strong></p>',32)])])}const m=i(t,[["render",s]]);export{o as __pageData,m as default};
